export const buildPropertyDefinitionText=(e,t)=>void 0===t?buildPropertyName(e):'<code class="unbreakable-text"><span class="property">'+e+"</span>: "+t+"</code>";export const buildPropertyName=e=>'<code class="unbreakable-text"><span class="property">'+e+"</span></code>";export const buildPropertyValue=e=>'<code class="unbreakable-text">'+e+"</code>";export const isFlexContainer=e=>{if(!e)return!1;const t=e.get("display");return"flex"===t||"inline-flex"===t};export const isInlineElement=e=>!!e&&"inline"===e.get("display");const possiblyReplacedElements=new Set(["audio","canvas","embed","iframe","img","input","object","video"]);export const isPossiblyReplacedElement=e=>!!e&&possiblyReplacedElements.has(e);export const isGridContainer=e=>{if(!e)return!1;const t=e.get("display");return"grid"===t||"inline-grid"===t};export const isMulticolContainer=e=>{if(!e)return!1;const t=e.get("column-width"),n=e.get("column-count");return"auto"!==t||"auto"!==n};